def validate_range(df, col, lo, hi):
    bad = df[(df[col] < lo) | (df[col] > hi)]
    return bad

def validate_unique(df, col):
    return not df[col].is_unique

def validate_consistency(df, earlier_col, later_col):
    bad = df[df[later_col] < df[earlier_col]]
    return bad

